// Messages.properties: greeting=Hello
// Messages_es.properties: greeting=Hola
Locale.setDefault(Locale.of("es"));

ResourceBundle rb = ResourceBundle.getBundle("Messages", Locale.of("de", "DE"));
System.out.println(rb.getString("greeting")); // "Hola" -- NO "Hello"

class ClassMessages extends ListResourceBundle {
    protected Object[][] getContents() {
        return new Object[][] { {"greeting", "Hi from class"} };
    }
}
ResourceBundle rb = ResourceBundle.getBundle("ClassMessages");
rb.getString("greeting"); // "Hi from class"

